from pathlib import Path
OUT=Path(__file__).resolve().parent;RUN=OUT.parent;ROOT=Path.cwd();summary=json.loads((RUN/'deepseek/summary.json').read_text());local=json.loads((RUN/'local/current-results.json').read_text());records={r['file']:r for r in json.loads((RUN/'deepseek/current-results.json').read_text())};selected={r['file']:r for r in json.loads((RUN/'selection.json').read_text())};rows=[];cards=[];total_before=total_after=0
h=lambda x:html.escape(str(x));pretty=lambda c:c.replace('_',' ').title()
md=['# Final readable report: selected 15 resumes','','## Did this run use DeepSeek?','','**Yes.** The saved run log says `cached: 0`, `new_attempts: 15`, model `deepseek-flash`, connection `ready`. The saved checkpoints record 16 classification requests with returned token usage; provider-decisions/ contains the saved response contents. The runner loads the existing key from `.env` automatically. You do not have to type a key at each run. The large provider prompt-cache-hit count is server-side input caching; it does not mean these were offline responses or free requests. Actual monetary cost was not calculated.','','This report was generated only from those saved records. **No new API calls or resume processing were performed to create it.**','','## Which report should you read?','','This report describes `reports/pilot-full-review-20261020-072948/`. The older `reports/pilot_fallback_20261020_live_v2/report.md` is a different run with a different fallback policy. Neither report is live status for the other.','','## Main result','','All 15 completed local extraction/block detection and were then sent to DeepSeek for review of assigned and unresolved text. The local stages ran on the bounded set of 15 copied PDFs before the DeepSeek stage began. DeepSeek reused those local outputs rather than extracting the PDF itself. Fourteen documents ended with all extracted text assigned. Java Aws backend still has six unassigned text spans. Assignment completion does not establish that the blocks or relationships are correct.','','| Resume | Unassigned meaningful spans after local processing | After DeepSeek | Requests | Outcome |','|---|---:|---:|---:|---|']
for row in local:
 file=row['file'];r=records.get(file,{});id=hashlib.sha256(file.encode()).hexdigest()[:20];a=json.loads((RUN/'deepseek/documents'/(id+'.json')).read_text());els=a['extraction']['elements'];before=a['local_sections'];after=a['reviewed_sections'];state=after.get('metadata',{}).get('llm_review',{})
 def meaningful(b):
  e=els[b['source_element_index']]
  return bool(b['text'].strip()) and e.get('type')!='PageBreak' and not(e.get('type')=='Footer' and re.fullmatch(r'\s*(?:page\s*)?\d+(?:\s*(?:of|/)\s*\d+)?\s*',b['text'],re.I))
 n=sum(meaningful(b) for b in before['needs_review']);m=sum(meaningful(b) for b in after['needs_review']);total_before+=n;total_after+=m
 notes=[];dups=[(j,i) for i,e in enumerate(els) for j,v in enumerate(els[:i]) if e['text']==v['text'] and len(e['text'].split())>=25]
 if dups:notes.append('Repeated extracted passages require source review: '+', '.join(f'e{x}/e{y}' for x,y in dups)+'. Repetition can also be genuine in the original PDF; do not delete it automatically.')
 if file=='GAURAVAGRAWAL.pdf' and not any('achievements' in e['text'].casefold() for e in els):notes.append('Known source issue remains: page 2 Achievements heading is absent from this saved extraction.')
 if file=='Java Aws backend.pdf':notes.append('Source is a job-requirements template, not established candidate history. Review or exclude it explicitly; blank template fields should not be invented as resume facts.')
 if file=='PUPPYKUMARI.pdf':notes.append('Original PDF contains conflicting Role History/Career History dates. Human review must preserve or resolve that conflict and verify employer/title/date table rows.')
 if file=='Prasad PR.pdf':notes.append('Check PGSQL block boundaries and degree/institution/date relationships. Assigning all text alone does not validate them.')
 if file=='Rutuja Herekar.pdf':notes.append('Check that GenAI coursework and future QA application plans are not represented as past employment.')
 if file=='Pavan Bakku.pdf':notes.append('Check KEY ACHIEVEMENTS taxonomy and the separation of four work-history records.')
 status='All extracted text assigned; correctness unverified' if not m else 'Needs review: unassigned text remains'
 result={'file':file,'local_meaningful_unassigned':n,'final_meaningful_unassigned':m,'api_calls':r.get('api_calls',0),'llm_reviewed_units':state.get('reviewed_units'),'llm_changed_units':state.get('changed_units'),'final_sections':'; '.join(pretty(s['category']) for s in after['sections']),'outcome':status,'word_accuracy':'NOT_ESTABLISHED','section_accuracy':'NOT_ESTABLISHED','relationship_accuracy':'NOT_ESTABLISHED','source_hash_matches_selection':row.get('sha256')==selected[file]['sha256'],'notes':' '.join(notes)};rows.append(result)
 md.append(f"| {file} | {n} | {m} | {result['api_calls']} | {'Assigned' if m==0 else 'Needs review'}; accuracy unverified |")
 section_html=[]
 for label,response in [('After DeepSeek',after),('Before DeepSeek: local result',before)]:
  pieces=[]
  for s in response['sections']:
   text=s.get('text') or ''.join(b['text'] for b in s['blocks']);pieces.append(f'<section><h4>{h(pretty(s["category"]))}</h4><pre>{h(text)}</pre><small>{len(s["blocks"])} source spans; {len(s.get("entries",[]))} proposed entry groups. Entry count is not relationship accuracy.</small></section>')
  if response['needs_review']:pieces.append('<section class="warn"><h4>Unassigned source text</h4>'+''.join(f'<p><strong>Page {h(b.get("page_number"))}, source element {b["source_element_index"]}</strong></p><pre>{h(b["text"])}</pre>' for b in response['needs_review'] if b['text'].strip())+'</section>')
  section_html.append(f'<details {"open" if label=="After DeepSeek" else ""}><summary>{h(label)}</summary>'+''.join(pieces)+'</details>')
 cards.append(f'<article id="{id}"><h2>{h(file)}</h2><p><b>{h(status)}</b></p><p>Local unassigned: {n} → Final: {m}. DeepSeek requests: {r.get("api_calls",0)}. Units reviewed: {h(state.get("reviewed_units"))}; changed: {h(state.get("changed_units"))}. These are model actions, not proven corrections.</p>'+(''.join('<p class="warn">'+h(t)+'</p>' for t in notes))+''.join(section_html)+'</article>')
md+=['','## What the numbers mean','',f'- Meaningful unassigned spans: **{total_before} → {total_after}**. Raw local needs_review count was 160; two NagaVishnu whitespace spans are excluded from the meaningful count.',f'- API requests: **{summary["classification_api_calls"]}**, reviewing **15/15 documents**, including the two documents locally having zero unassigned spans. This was full review, not fallback-only.',f'- Actual recorded token usage: **{summary["usage"]["prompt_tokens"]:,} input + {summary["usage"]["completion_tokens"]:,} output = {summary["usage"]["total_tokens"]:,} tokens**.', '- Extracted-source invariant checks passed for all 15 in the saved run. They show source intervals were preserved; they cannot prove every original PDF word was extracted or every block was correct.', '- No independently source-bound human-approved ground truth has been established. Word accuracy, section accuracy and employer/title/date or degree/institution/year accuracy are therefore **not measured**. Do not describe 14/15 assignment completion as 93.33% accuracy.','','## Issues still requiring review']
for r in rows:
 if r['notes']:md+=['',f"**{r['file']}:** {r['notes']}"]
md+=['','## Read the actual blocks','','Open **index.html in this directory**. Each resume shows its detected sections as normal readable text, the local result for comparison, and any unassigned text. No API calls are made when opening it; no external scripts, fonts or analytics are included. The page contains personal resume information, so keep it private.','','## Final conclusion','','The recorded full-review workflow ran for all 15 and used DeepSeek. It assigned all extracted text in 14 documents and left six spans in the Java template unresolved. It has **not** established that these 14 resumes are accurate. Confirm the source-text defects, section taxonomy and employment/education record relationships against original PDFs before acceptance or scaling. No original PDF, annotation, provider response or previous report was changed while building this readable report.']
(OUT/'report.md').write_text('\n'.join(md)+'\n')
