intro=f'<h1>15-resume report — full DeepSeek review</h1><p><b>Yes, this run used DeepSeek: {summary["classification_api_calls"]} live requests for 15 documents.</b> The key was loaded automatically from .env. This page reads saved results only and makes no API calls.</p><p>Run: {h(RUN.name)}. All extracted text assigned in 14/15 documents. Meaningful unassigned spans: {total_before} → {total_after}. <b>Correctness and word/relationship accuracy remain unverified.</b></p><p>“Assigned” means text has a category; it does not mean the category or record relationship is correct.</p>'
nav='<nav><h2>Choose a resume</h2>'+''.join(f'<a href="#{hashlib.sha256(r["file"].encode()).hexdigest()[:20]}">{h(r["file"])} — {r["local_meaningful_unassigned"]} → {r["final_meaningful_unassigned"]} unassigned</a>' for r in rows)+'</nav>'
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>15-resume readable report</title><style>body{font:17px/1.6 system-ui,sans-serif;max-width:1100px;margin:auto;padding:28px;background:#f5f7fa;color:#152536}article,nav{background:white;padding:24px;margin:24px 0;border:1px solid #d3dde7;border-radius:10px}nav a{display:block;color:#145d9b}summary{font-weight:700;cursor:pointer;padding:12px;background:#edf3fa}section{padding:14px 0;border-bottom:1px solid #ddd}pre{font:inherit;white-space:pre-wrap;overflow-wrap:anywhere}.warn{background:#fff1d7;padding:12px}small{color:#526375}</style>'+intro+nav+''.join(cards)+'</html>')
print(json.dumps({'documents':len(rows),'meaningful_unassigned_before':total_before,'after':total_after,'requests_recorded':summary['classification_api_calls'],'new_api_calls':0,'html':str(OUT/'index.html')}))
